Item.method_code:
const { itemTypeName, itemId } = options;
const itemNode = window.getItem();
const currentClassification = aras.getItemProperty(itemNode, "classification");
const isFormResponsive = currentClassification === 'Responsive';
const disabled = ArasModules.item.isEditState(itemTypeName, itemId);
const hidden = ArasModules.item.isNew(itemTypeName, itemId);
const label = isFormResponsive ? aras.getResource('', 'form_editor.switch_to_classic') : aras.getResource('', 'form_editor.switch_to_responsive');

return {
	label: isFormResponsive ? '' : label,
	tooltip_template: isFormResponsive ? label : '',
	disabled,
	hidden
}
